ogx_truthfulqax_mc2_fi_fbv2_p0.process_results:
def process_results_mc2(doc, results):
    choices = doc["mc2_targets"]["choices"]
    num_choices = len(choices)
    lls, _ = zip(*results, strict=True)

    # metric_list includes acc_mutual_info, so construct_requests appends one
    # unconditional ("", choice) request per choice after the conditional ones.
    if len(lls) == 2 * num_choices:
        lls_cond, lls_uncond = lls[:num_choices], lls[num_choices:]
    elif len(lls) == num_choices:
        lls_cond, lls_uncond = lls, None
    else:
        raise ValueError(
            f"Expected {num_choices} or {2 * num_choices} loglikelihoods, got {len(lls)}"
        )

    split_idx = list(doc["mc2_targets"]["labels"]).index(0)
    completion_len = [len(c) for c in choices]
    # A handful of docs in this dataset have empty-string choices (e.g. doc 275
    # of the validation split); char-length normalization is undefined for
    # those, so treat them as carrying no probability mass (exp(-inf) == 0)
    # instead of crashing the whole run with a ZeroDivisionError.
    lls_norm = [
        ll / cl if cl > 0 else float("-inf")
        for ll, cl in zip(lls_cond, completion_len)
    ]

    result = {
        "acc": _mc2_score(lls_cond, split_idx),
        "acc_norm": _mc2_score(lls_norm, split_idx),
        # Char-length-normalized loglikelihood of the best true choice, mirroring
        # ConfigurableTask's built-in multi-target norm_loglikelihood_corr (task.py).
        "norm_loglikelihood_corr": max(
            (
                lls_cond[i] / completion_len[i]
                for i in range(split_idx)
                if completion_len[i] > 0
            ),
            default=float("nan"),
        ),
    }

    if lls_uncond is not None:
        lls_mutual_info = [c - u for c, u in zip(lls_cond, lls_uncond, strict=True)]
        result["acc_mutual_info"] = _mc2_score(lls_mutual_info, split_idx)

    return result

